begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select has_table('public','notifications','Notification persistence exists');
select ok((select relrowsecurity from pg_class where oid='public.notifications'::regclass),'Notification RLS enabled');
select ok(not has_table_privilege('anon','public.notifications','SELECT,INSERT,UPDATE,DELETE'),'Anonymous notification access closed');
select ok(not has_table_privilege('authenticated','public.notifications','INSERT,UPDATE,DELETE'),'Direct member writes closed');
select ok(not has_table_privilege('service_role','public.notifications','SELECT,INSERT,UPDATE,DELETE'),'No service notification bypass');
select ok(not has_schema_privilege('authenticated','notification_private','USAGE'),'Private persistence schema closed');
select ok(not has_function_privilege('authenticated','notification_private.prepare_notification()','EXECUTE'),'Private persistence function closed');
insert into auth.users(id,email) select ('21900000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'notification-'||n||'@example.invalid' from generate_series(1,6)n;
insert into public.memberships(user_id,role) select ('21900000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,case when n=4 then 'admin' else 'member' end::public.member_role from generate_series(1,5)n;
insert into public.profiles(user_id,display_name,home_airport,pilot_designation) select ('21900000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'Notification pilot','KPAO','licensed' from generate_series(1,5)n;
update public.memberships set status='disabled',disabled_at=now(),disabled_reason='Owned test' where user_id='21900000-0000-4000-8000-000000000005';
insert into public.flights(id,owner_id,departure_airport,destination_airport,departure_at,departure_timezone,aircraft_description,pilot_places,visibility,notes) values('21920000-0000-4000-8000-000000000001','21900000-0000-4000-8000-000000000001','KPAO','KSQL',now()+interval '2 days','UTC','Notification C172',2,'PRIVATE','Private post notification canary');
insert into public.flight_recipients(flight_id,user_id) values('21920000-0000-4000-8000-000000000001','21900000-0000-4000-8000-000000000002');
insert into public.flight_requests(id,flight_id,requester_id) values('21930000-0000-4000-8000-000000000001','21920000-0000-4000-8000-000000000001','21900000-0000-4000-8000-000000000002');
select is((select count(*)::integer from public.notifications),0,'Privileged source fixtures do not generate operation events');
insert into public.notifications(id,event_type,request_id,event_key,created_at) values('21960000-0000-4000-8000-000000000001','request_received','21930000-0000-4000-8000-000000000001','forged-key','2000-01-01');
select is((select recipient_id::text from public.notifications where id='21960000-0000-4000-8000-000000000001'),'21900000-0000-4000-8000-000000000001','Request recipient is authoritative owner');
select ok((select event_key like 'request_received:21930000-0000-4000-8000-000000000001:%' and created_at>'2026-01-01' and read_at is null from public.notifications where id='21960000-0000-4000-8000-000000000001'),'Canonical event key, server chronology and unread initial state');
create temporary table notification_snapshot as select * from public.notifications;
insert into public.notifications(event_type,request_id) values('request_received','21930000-0000-4000-8000-000000000001') on conflict(recipient_id,event_key) do nothing;
select is((select count(*)::integer from public.notifications),1,'Exact source retry inserts once');
select results_eq('select * from public.notifications order by id','select * from notification_snapshot order by id','Exact retry preserves original record/time');
select throws_ok($$insert into public.notifications(event_type,request_id) values('request_accepted','21930000-0000-4000-8000-000000000001')$$,'23514',null,'Acceptance requires accepted source');
select throws_ok($$insert into public.notifications(event_type,request_id,recipient_id) values('request_received','21930000-0000-4000-8000-000000000001','21900000-0000-4000-8000-000000000003')$$,'23514',null,'Wrong recipient cannot be supplied');
select throws_ok($$insert into public.notifications(event_type,request_id,message_id) values('request_received','21930000-0000-4000-8000-000000000001',gen_random_uuid())$$,'23514',null,'Mixed targets rejected');
select throws_ok($$insert into public.notifications(event_type) values('message_received')$$,'23514',null,'Missing target rejected');
select throws_ok($$insert into public.notifications(event_type,request_id) values('email','21930000-0000-4000-8000-000000000001')$$,'23514',null,'Unknown event rejected');
select throws_ok($$insert into public.notifications(event_type,request_id) values('request_received','21930000-0000-4000-8000-000000000099')$$,'23503',null,'Unknown source rejected');
select throws_ok($$insert into public.notifications(event_type,request_id,read_at) values('request_received','21930000-0000-4000-8000-000000000001',now())$$,'23514',null,'Caller cannot create read notification');
update public.flight_requests set status='accepted' where id='21930000-0000-4000-8000-000000000001';
insert into public.notifications(id,event_type,request_id) values('21960000-0000-4000-8000-000000000002','request_accepted','21930000-0000-4000-8000-000000000001');
select is((select recipient_id::text from public.notifications where event_type='request_accepted'),'21900000-0000-4000-8000-000000000002','Acceptance recipient is requester');
select throws_ok($$insert into public.notifications(event_type,request_id) values('request_received','21930000-0000-4000-8000-000000000001')$$,'23514',null,'Pending event cannot be created from accepted source');
insert into public.conversations(id,flight_request_id,owner_id,requester_id) values('21940000-0000-4000-8000-000000000001','21930000-0000-4000-8000-000000000001','21900000-0000-4000-8000-000000000001','21900000-0000-4000-8000-000000000002');
create function pg_temp.actor(n integer) returns text language sql as $$select set_config('request.jwt.claims',json_build_object('sub',('21900000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'role','authenticated','user_metadata',json_build_object('role','admin'))::text,true);$$;
set local role authenticated;
select pg_temp.actor(2);
select public.send_conversation_message('21940000-0000-4000-8000-000000000001','21950000-0000-4000-8000-000000000001','Private message notification canary');
reset role;
-- The guarded message operation generated this event atomically.
select is((select recipient_id::text from public.notifications where event_type='message_received'),'21900000-0000-4000-8000-000000000001','Message recipient is the other immutable participant');
select is((select event_key from public.notifications where event_type='message_received'),'message_received:21950000-0000-4000-8000-000000000001','Message retry identity is immutable message UUID');
insert into public.notifications(event_type,message_id) values('message_received','21950000-0000-4000-8000-000000000001') on conflict(recipient_id,event_key) do nothing;
select is((select count(*)::integer from public.notifications),3,'Message and request retries do not duplicate');
select ok((select bool_and(to_jsonb(n)::text not like '%notification canary%') from public.notifications n),'No message body or post snapshots copied');
set local role authenticated;
select pg_temp.actor(1);
select public.send_conversation_message('21940000-0000-4000-8000-000000000001','21950000-0000-4000-8000-000000000002','Reciprocal private notification canary');
reset role;
select is((select count(*)::integer from public.notifications),4,'Reciprocal message operation generates its event');
select is((select recipient_id::text from public.notifications where message_id='21950000-0000-4000-8000-000000000002'),'21900000-0000-4000-8000-000000000002','Owner message notifies requester, never its sender');
set local role authenticated;
select pg_temp.actor(1);
select is((select count(*)::integer from public.notifications),2,'Owner reads only their request/message notifications');
select pg_temp.actor(2);
select is((select count(*)::integer from public.notifications),2,'Requester reads only their acceptance and owner message');
select pg_temp.actor(3);
select is((select count(*)::integer from public.notifications),0,'Unrelated member and forged metadata have no read');
select pg_temp.actor(4);
select is((select count(*)::integer from public.notifications),0,'Administrator has no recipient bypass');
select throws_ok($$insert into public.notifications(event_type,request_id) values('request_received','21930000-0000-4000-8000-000000000001')$$,'42501',null,'Admin cannot forge notifications');
select throws_ok($$update public.notifications set read_at=now()$$,'42501',null,'Mark-read direct writes remain closed');
select throws_ok($$delete from public.notifications$$,'42501',null,'Direct deletion closed');
select pg_temp.actor(6);
select is((select count(*)::integer from public.notifications),0,'Unadmitted identity reads no notifications');
reset role;
select throws_ok($$update public.notifications set event_key='changed'$$,'23514',null,'Notification event metadata immutable');
select throws_ok($$delete from public.messages where id='21950000-0000-4000-8000-000000000001'$$,'23503',null,'Target deletion cannot silently remove notification history');
set local role authenticated;
select pg_temp.actor(1);
select public.change_flight_recipient('21920000-0000-4000-8000-000000000001','21900000-0000-4000-8000-000000000002',false);
select pg_temp.actor(2);
select is((select count(*)::integer from public.notifications),2,'PRIVATE removal retains own notification history');
select is((select count(*)::integer from public.flights where id='21920000-0000-4000-8000-000000000001'),0,'Notification reference restores no PRIVATE target access');
reset role;
update public.memberships set status='disabled',disabled_at=now(),disabled_reason='Owned test' where user_id='21900000-0000-4000-8000-000000000001';
set local role authenticated;
select pg_temp.actor(1);
select is((select count(*)::integer from public.notifications),0,'Existing identity loses notification reads when disabled');
reset role;
select throws_ok($$insert into public.notifications(event_type,message_id) values('message_received','21950000-0000-4000-8000-000000000001')$$,'23514',null,'Disabled recipient cannot receive new persistence');
update public.memberships set status='active',disabled_at=null,disabled_reason=null where user_id='21900000-0000-4000-8000-000000000001';
-- The same request record can have a genuinely new pending/acceptance occurrence.
insert into public.flight_recipients(flight_id,user_id) values('21920000-0000-4000-8000-000000000001','21900000-0000-4000-8000-000000000002');
-- Audience removal cancelled the first request, so use an independently withdrawn source.
insert into public.flight_recipients(flight_id,user_id) values('21920000-0000-4000-8000-000000000001','21900000-0000-4000-8000-000000000003');
insert into public.flight_requests(id,flight_id,requester_id) values('21930000-0000-4000-8000-000000000002','21920000-0000-4000-8000-000000000001','21900000-0000-4000-8000-000000000003');
insert into public.notifications(event_type,request_id) values('request_received','21930000-0000-4000-8000-000000000002');
update public.flight_requests set status='withdrawn' where id='21930000-0000-4000-8000-000000000002';
select throws_ok($$insert into public.notifications(event_type,request_id) values('request_received','21930000-0000-4000-8000-000000000002')$$,'23514',null,'Withdrawn state cannot create pending notification');
update public.flight_requests set status='pending' where id='21930000-0000-4000-8000-000000000002';
insert into public.notifications(event_type,request_id) values('request_received','21930000-0000-4000-8000-000000000002');
select is((select count(*)::integer from public.notifications where request_id='21930000-0000-4000-8000-000000000002' and event_type='request_received'),2,'Eligible same-record resubmission has a new event identity');
update public.flight_requests set status='accepted' where id='21930000-0000-4000-8000-000000000002';
insert into public.notifications(event_type,request_id) values('request_accepted','21930000-0000-4000-8000-000000000002');
update public.flight_requests set status='withdrawn' where id='21930000-0000-4000-8000-000000000002';
update public.flight_requests set status='pending' where id='21930000-0000-4000-8000-000000000002';
update public.flight_requests set status='accepted' where id='21930000-0000-4000-8000-000000000002';
insert into public.notifications(event_type,request_id) values('request_accepted','21930000-0000-4000-8000-000000000002');
select is((select count(*)::integer from public.notifications where request_id='21930000-0000-4000-8000-000000000002' and event_type='request_accepted'),2,'Later reacceptance is distinct from retry of its prior acceptance');
set local role anon;
select throws_ok($$select * from public.notifications$$,'42501',null,'Anonymous actual SELECT rejected');
reset role;
select * from finish();
rollback;
